@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "~/Views/Shared/_Layout.cshtml";
    ViewData["Title"] = Model.Title;
    var posts = Model.Children<BlogPost>()?.OrderByDescending(p => p.PublishDate).ToList() ?? new List<BlogPost>();
}

<section class="mb-10">
    <h1 class="text-4xl font-bold tracking-tight text-slate-900">@Model.Title</h1>
    @if (!string.IsNullOrWhiteSpace(Model.Intro))
    {
        <p class="mt-3 text-lg text-slate-600">@Model.Intro</p>
    }
</section>

@await Html.GetBlockGridHtmlAsync(Model, "body")

<section class="mt-12">
    <h2 class="mb-6 text-2xl font-semibold text-slate-900">Latest posts</h2>
    <div class="grid gap-8 sm:grid-cols-2">
        @foreach (var post in posts)
        {
            var imageUrl = post.ListingImage?.GetCropUrl(width: 800, height: 450);
            <a href="@post.Url()" class="group overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:shadow-md">
                @if (!string.IsNullOrEmpty(imageUrl))
                {
                    <img src="@imageUrl" alt="@post.Title" class="aspect-video w-full object-cover" loading="lazy" />
                }
                <div class="p-5">
                    <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-xs uppercase tracking-wide text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</time>
                    <h3 class="mt-1 text-lg font-semibold text-slate-900 group-hover:text-blue-700">@post.Title</h3>
                    <p class="mt-2 text-sm text-slate-600">@post.Excerpt</p>
                </div>
            </a>
        }
    </div>
</section>

